def main():
    raw = base64.b64decode(EXPORT_BASE64)
    if hashlib.sha256(raw).hexdigest() != EXPORT_SHA256:
        raise SystemExit("Source archive checksum mismatch")
    destination = Path("skyeatlas").resolve()
    if destination.exists():
        raise SystemExit("skyeatlas already exists; choose an empty directory")
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        for name in archive.namelist():
            if not (destination / name).resolve().is_relative_to(destination):
                raise SystemExit("Unsafe archive path")
        archive.extractall(destination)
    print("Preserved source extracted to skyeatlas/")

if __name__ == "__main__":
    main()
